<?php $prefix='blocks['.$i.']'; ?><fieldset class="cms-block" data-theme-block><legend>بخش صفحه اصلی</legend><div class="form-row"><div class="field"><label>نوع ویجت</label><?= CHtml::dropDownList($prefix.'[block_type]',$block['block_type'],ThemeOptions::blockTypes(),array('data-block-type'=>'1')) ?></div><div class="field"><label>عنوان بخش</label><?= CHtml::textField($prefix.'[title]',$block['title']) ?></div><div class="field"><label>ترتیب</label><?= CHtml::numberField($prefix.'[sort_order]',$block['sort_order'],array('min'=>0,'max'=>1000)) ?></div></div><div class="form-row"><div class="field" data-block-collection <?= $block['block_type']==='collection'?'':'hidden' ?>><label>کالکشن</label><?= CHtml::dropDownList($prefix.'[collection_id]',$block['collection_id'],$collections,array('prompt'=>'منتخب‌های پیش‌فرض')) ?></div><div class="field" data-block-category <?= $block['block_type']==='category_products'?'':'hidden' ?>><label>دسته‌بندی محصولات</label><?= CHtml::dropDownList($prefix.'[category_id]',$block['category_id']??null,$categories,array('prompt'=>'انتخاب دسته‌بندی','required'=>$block['block_type']==='category_products')) ?><small class="muted">شامل محصولات زیرشاخه‌ها</small></div><div class="field"><label>چیدمان</label><?= CHtml::dropDownList($prefix.'[presentation]',$block['presentation'],array('grid'=>'شبکه محصولات','carousel'=>'اسلایدر افقی')) ?></div><div class="field"><label>کارت محصول</label><?= CHtml::dropDownList($prefix.'[card_style]',$block['card_style'],array('standard'=>'استاندارد','compact'=>'فشرده','editorial'=>'تصویرمحور')) ?></div><div class="field"><label>تعداد</label><?= CHtml::numberField($prefix.'[item_limit]',$block['item_limit'],array('min'=>1,'max'=>24)) ?></div></div><div class="check-field"><?= CHtml::checkBox($prefix.'[is_enabled]',(bool)$block['is_enabled']) ?><label>نمایش این بخش</label></div><button type="button" class="btn btn-outline btn-sm" data-remove-block>حذف بخش</button></fieldset>
